# Generated by build.py from recipe.yml for recipe surl-smoke-test-every-listener. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/health.txt'), "ok`n")
[IO.File]::WriteAllText((Join-Path $PWD 'smoke.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Smoke-tests listeners: one quick request to each URL in turn, in its own protocol. A`n# listener passes if it answers at all, a refusal included. The first that does not answer`n# within 3 seconds ends the run with curl's exit code; the rest are not tried.`n# Usage: sh smoke.sh <url>...`nfor url in `"`$@`"; do`n  case `$url in`n    http*) ask= ;;              # a GET; any status will do`n    *)     ask=`"-X NOOP`" ;;     # FTP, SMTP, IMAP: a command that changes nothing`n  esac`n  got=`$(curl -s -m 3 `$ask -o /dev/null -w '%{response_code} %{num_connects}' `"`$url`")`n  status=`$?`n  code=`${got% *}; connects=`${got#* }`n  if [ `"`$status`" -ne 0 ] && [ `"`$code`" = 000 ]; then`n    if [ `"`$connects`" -eq 0 ]; then how=`"no connection`"; else how=`"connected, no reply`"; fi`n    echo `"FAIL `$url: curl exit `$status, `$how`"`n    exit `"`$status`"`n  fi`n  if [ `"`$code`" = 000 ]; then echo `"ok `${url%%:*}: curl exit `$status`"`n  else echo `"ok `${url%%:*}: curl exit `$status, reply `$code`"; fi`ndone`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--mail-domain', 'example.com', '--mailbox', 'app@example.com:secret', 'http://127.0.0.1:8080/', 'ftp://127.0.0.1:8081/', 'smtp://127.0.0.1:8082/', 'imap://127.0.0.1:8083/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh smoke.sh http://127.0.0.1:8080/ ftp://127.0.0.1:8081/ smtp://127.0.0.1:8082/ imap://127.0.0.1:8083/ } finally { Stop-Process $server0 }
